use super::*;

/// One sentence, in the terms the question was asked in.
pub fn summarise_viable(v: &ViableIncome) -> String {
    let base = format!(
        "{} minor units a month keeps everything current, measured on {} — the worst month, not the average",
        v.headline.worst_month.minor, v.headline.worst_month_name
    );
    match v.gaps.as_ref().and_then(|gs| gs.iter().find(|g| g.tier == Tier::Current)) {
        None => base,
        Some(g) if g.clears => format!("{base}; the low income band already clears it"),
        Some(g) => format!("{base}; the low income band is short by {}", g.shortfall.minor),
    }
}
